<?php if($search_text!==''):?><div class="card shadow-sm"><div class="card-header"><h2 class="card-title mb-0">Ranked Suggestions</h2></div><div class="card-body"><div class="table-responsive"><table class="table table-striped table-hover align-middle"><thead><tr><th>Standard Item</th><th>UOM</th><th>Revision</th><th>Similarity</th><th>Confidence</th><th>Explanation</th></tr></thead><tbody><?php foreach($results as$row):?><?php $recommendable=!empty($row->confidence->is_recommendable);?><tr><td><a href="<?=site_url('standard-cost-items/'.$row->cost_item_id)?>"><?=html_escape($row->enterprise_cost_code?:$row->cost_item_uid)?></a><div class="small text-body-secondary"><?=html_escape($row->standard_item_name)?></div></td><td><?=html_escape($row->uom_code?:'Not recorded')?></td><td><?=html_escape($row->revision_no.' · '.$row->revision_status)?></td><td><strong><?=number_format($row->similarity_score,2)?></strong> / 100</td><td><span class="badge text-bg-<?=$recommendable?'success':'secondary'?>"><?=html_escape($row->confidence->confidence_name)?></span><div class="small mt-1"><?=$recommendable?'Recommendable candidate':'Review required'?></div></td><td><?=html_escape($row->explanation)?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$results):?><p class="text-body-secondary mb-0">No standard items matched the meaningful terms in this description.</p><?php endif;?></div></div><?php else:?><div class="card shadow-sm"><div class="card-body text-body-secondary">Enter an item description to rank current active standard cost-item revisions. Adding a UOM improves the score only when it agrees with the candidate.</div></div><?php endif;?>
